import java.awt.*
import java.util.Properties
import javax.swing.*
data class Event(val day:Int,val start:Int,val end:Int,val title:String)
fun minutes(text:String):Int{val p=text.trim().split(':');require(p.size==2);val h=p[0].toInt();val m=p[1].toInt();require(h in 0..23&&m in 0..59);return h*60+m}
fun clock(n:Int)="%02d:%02d".format(n/60,n%60)
fun validate(events:List<Event>){require(events.size<=500);events.forEach{require(it.day in 0..6&&it.start in 0..1439&&it.end in 1..1440&&it.start<it.end&&it.title.isNotBlank())};for(i in events.indices)for(j in 0 until i)require(events[i].day!=events[j].day||events[i].start>=events[j].end||events[j].start>=events[i].end){"Overlapping events"}}
fun encode(events:List<Event>):Properties{validate(events);val p=Properties();p.setProperty("count",events.size.toString());events.forEachIndexed{i,e->p.setProperty("$i.day",e.day.toString());p.setProperty("$i.start",e.start.toString());p.setProperty("$i.end",e.end.toString());p.setProperty("$i.title",e.title)};return p}
fun decode(p:Properties):MutableList<Event>{val n=p.getProperty("count").toInt();require(n in 0..500);val out=(0 until n).map{Event(p.getProperty("$it.day").toInt(),p.getProperty("$it.start").toInt(),p.getProperty("$it.end").toInt(),p.getProperty("$it.title"))}.toMutableList();validate(out);return out}
fun main(args:Array<String>){if(args.contains("--self-test")){val events=listOf(Event(0,540,600,"Study"),Event(0,600,660,"Break"));check(decode(encode(events))==events);check(minutes("09:30")==570);check(runCatching{validate(events+Event(0,550,560,"Conflict"))}.isFailure);println("Time parsing, interval boundaries, conflicts, and persistence passed");return};SwingUtilities.invokeLater{val days=arrayOf("Mon","Tue","Wed","Thu","Fri","Sat","Sun");var events=mutableListOf<Event>();val frame=JFrame("Weekly Timetable Planner").apply{defaultCloseOperation=JFrame.EXIT_ON_CLOSE;setSize(900,620)};val root=JPanel(BorderLayout(10,10));frame.contentPane=root;val list=JList<String>();val model=DefaultListModel<String>();list.model=model;root.add(JScrollPane(list),BorderLayout.CENTER);val bar=JPanel();val day=JComboBox(days);val start=JTextField("09:00",5);val end=JTextField("10:00",5);val title=JTextField(20);bar.add(day);bar.add(start);bar.add(end);bar.add(title);root.add(bar,BorderLayout.NORTH);val controls=JPanel();root.add(controls,BorderLayout.SOUTH);fun draw(){model.clear();events.forEach{model.addElement("${days[it.day]} ${clock(it.start)}–${clock(it.end)} ${it.title}")}};fun button(text:String,action:()->Unit){val b=JButton(text);controls.add(b);b.addActionListener{try{action();draw()}catch(e:Exception){JOptionPane.showMessageDialog(frame,e.message)}}};button("Add"){val next=events+Event(day.selectedIndex,minutes(start.text),minutes(end.text),title.text);validate(next);events=next.sortedWith(compareBy<Event>{it.day}.thenBy{it.start}).toMutableList()};button("Remove selected"){if(list.selectedIndex in events.indices)events.removeAt(list.selectedIndex)};button("Save"){val c=JFileChooser();if(c.showSaveDialog(frame)==JFileChooser.APPROVE_OPTION)c.selectedFile.bufferedWriter().use{encode(events).store(it,"Timetable")}};button("Open"){val c=JFileChooser();if(c.showOpenDialog(frame)==JFileChooser.APPROVE_OPTION){val p=Properties();c.selectedFile.bufferedReader().use{p.load(it)};events=decode(p)}};draw();frame.setLocationRelativeTo(null);frame.isVisible=true}}
